options.customCss:
:root {
  /* Cybersecurity Theme */
  --chat--color--primary: #2563eb;
  --chat--color--primary-shade-50: #1d4ed8;
  --chat--color--primary--shade-100: #1e40af;

  --chat--color--secondary: #0ea5e9;
  --chat--color-secondary-shade-50: #0284c7;

  --chat--color-white: #ffffff;
  --chat--color-light: #f8fafc;
  --chat--color-light-shade-50: #e2e8f0;
  --chat--color-light-shade-100: #cbd5e1;
  --chat--color-medium: #94a3b8;
  --chat--color-dark: #0f172a;
  --chat--color-disabled: #cbd5e1;
  --chat--color-typing: #475569;

  /* Layout */
  --chat--spacing: 1rem;
  --chat--border-radius: 0.5rem;
  --chat--transition-duration: 0.15s;
  --chat--font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;

  /* Chat Window */
  --chat--window--width: 450px;
  --chat--window--height: 650px;
  --chat--window--bottom: 1rem;
  --chat--window--right: 1rem;
  --chat--window--z-index: 9999;
  --chat--window--border: 1px solid #e2e8f0;
  --chat--window--border-radius: 0.75rem;
  --chat--window--margin-bottom: 1rem;

  /* Header */
  --chat--header-height: auto;
  --chat--header--padding: 1.25rem;
  --chat--header--background: #0f172a;
  --chat--header--color: #ffffff;
  --chat--header--border-top: none;
  --chat--header--border-bottom: none;
  --chat--header--border-left: none;
  --chat--header--border-right: none;

  --chat--heading--font-size: 1.5em;
  --chat--subtitle--font-size: 0.9rem;
  --chat--subtitle--line-height: 1.5;

  /* Messages */
  --chat--message--font-size: 0.95rem;
  --chat--message--padding: 0.9rem;
  --chat--message--border-radius: 0.6rem;
  --chat--message-line-height: 1.5;
  --chat--message--margin-bottom: 0.8rem;

  --chat--message--bot--background: #ffffff;
  --chat--message--bot--color: #0f172a;
  --chat--message--bot--border: 1px solid #e2e8f0;

  --chat--message--user--background: #2563eb;
  --chat--message--user--color: #ffffff;
  --chat--message--user--border: none;

  --chat--message--pre--background: #f1f5f9;
  --chat--messages-list--padding: 1rem;

  /* Toggle Button */
  --chat--toggle--size: 60px;
  --chat--toggle--width: 60px;
  --chat--toggle--height: 60px;
  --chat--toggle--border-radius: 50%;
  --chat--toggle--background: #2563eb;
  --chat--toggle--hover--background: #1d4ed8;
  --chat--toggle--active--background: #1e40af;
  --chat--toggle--color: #ffffff;

  /* Input */
  --chat--textarea--height: 50px;
  --chat--textarea--max-height: 30rem;
  --chat--input--font-size: 0.95rem;
  --chat--input--border: 1px solid #cbd5e1;
  --chat--input--border-radius: 0.5rem;
  --chat--input--padding: 0.8rem;
  --chat--input--background: #ffffff;
  --chat--input--text-color: #0f172a;
  --chat--input--line-height: 1.5;

  /* Buttons */
  --chat--button--padding: 0.65rem 1rem;
  --chat--button--border-radius: 0.5rem;
  --chat--button--font-size: 0.95rem;
  --chat--button--line-height: 1;

  --chat--button--color--primary: #ffffff;
  --chat--button--background--primary: #2563eb;
  --chat--button--border--primary: none;

  --chat--button--color--primary--hover: #ffffff;
  --chat--button--background--primary--hover: #1d4ed8;

  /* Send Button */
  --chat--input--send--button--background: #ffffff;
  --chat--input--send--button--color: #2563eb;
  --chat--input--send--button--background-hover: #eff6ff;
  --chat--input--send--button--color-hover: #1d4ed8;

  /* Body */
  --chat--body--background: #f8fafc;
  --chat--footer--background: #ffffff;
  --chat--footer--color: #0f172a;
}

/* Message width */
.chat-message {
  max-width: 75%;
}
